--   Petrick Mateus - RM575301
-- -----------------------------------------------------------------------------
-- Ordem de execução no Oracle: ddl_climalink.sql > dml_climalink.sql > sql_climalink.sql
-- =============================================================================
-- =============================================================================
-- ClimaLink - Global Solutions 2026 - 1TSCOR
-- dml_climalink.sql  |  Carga de dados (executar depois do ddl_climalink.sql)
--
-- FONTES
--   * T_CLK_AVISO_INMET e T_CLK_AVISO_MESORREGIAO: BASE PÚBLICA REAL.
--     Avisos meteorológicos do INMET, feed RSS https://apiprevmet3.inmet.gov.br/avisos/rss,
--     baixados em 18/11/2026 e tratados por ingestion_inmet.py; INSERTs dos avisos
--     gerados por csv_to_sql_inmet.py. Associações limitadas às mesorregiões
--     do piloto ClimaLink.
--   * T_CLK_MESORREGIAO e T_CLK_MUNICIPIO: códigos e nomes oficiais do IBGE;
--     população aproximada (ordem de grandeza do Censo 2022) e nº de estações
--     sintéticos.
--   * T_CLK_MEDICAO_AMBIENTAL: dados SINTÉTICOS (fl_sintetico = 'S'), com estrutura
--     inspirada em MapBiomas Fogo e CEMADEN, criados para se relacionar com os
--     avisos reais.
-- =============================================================================
SET DEFINE OFF;
ALTER SESSION SET NLS_DATE_FORMAT = 'DD/MM/YYYY HH24:MI';

-- 1) T_CLK_MESORREGIAO (28 registros)

-- 2) T_CLK_MUNICIPIO (39 registros) - fonte: IBGE (código e nome oficiais)

-- 3) T_CLK_AVISO_INMET (12 registros) - BASE PÚBLICA REAL: INMET (RSS de avisos)
--    Bloco gerado automaticamente por csv_to_sql_inmet.py (item 6) a partir de
--    ./2026.2/gs/data/inmet/inmet_avisos.csv - igual a ./2026.2/gs/data/sql/insert_t_clk_aviso_inmet.sql

-- 4) T_CLK_AVISO_MESORREGIAO (70 registros) - áreas reais de cada aviso (recorte do piloto)

-- 5) T_CLK_MEDICAO_AMBIENTAL (221 registros) - SINTÉTICOS (MapBiomas Fogo / CEMADEN)

COMMIT;

-- =============================================================================
-- 6) UPDATE - situações reais de uso
-- =============================================================================

-- 6.1 Rotina diária de atualização: na coleta de 18/11/2026, os avisos cuja
--     vigência já terminou passam de ATIVO para ENCERRADO.
--     (em produção a data de referência seria SYSDATE)
UPDATE t_clk_aviso_inmet
   SET st_aviso = 'ENCERRADO'
 WHERE st_aviso = 'ATIVO'
   AND dt_fim < TO_DATE('2026-11-18 00:00', 'YYYY-MM-DD HH24:MI');

-- 6.2 A Defesa Civil informou a instalação de uma nova estação pluviométrica
--     em São Desidério (BA), município rural com baixa cobertura.
UPDATE t_clk_municipio
   SET qt_estacoes_pluviometricas = qt_estacoes_pluviometricas + 1
 WHERE cd_ibge = 2928901;

-- =============================================================================
-- 7) DELETE - situação real de uso
-- =============================================================================

-- 7.1 Limpeza de qualidade: registros de área queimada abaixo de 5 ha
--     são tratados como ruído e descartados das análises.
DELETE FROM t_clk_medicao_ambiental
 WHERE tp_indicador = 'AREA_QUEIMADA_HA'
   AND vl_medicao < 5;

COMMIT;
